"""RECHECK-HAS-POSE: in a real run log the recheck sits between two pose records (ref b3).

A replay places the Scout from its `pose` records (1 Hz). The recheck after a slab shift (the first `plan`
strictly after the shift with status ok whose cells miss the slab's core) must sit between two of them:
a pose at or before it and a pose at or after it, at most POSE_GAP_S apart, so the Scout's position at
the recheck is known from the log on both sides, never extrapolated past its last pose.

Real logs: REAL (seed 0 on main, both 9/9): every pose, the shift and mapped records and the plans in the
2 s after the shift, of a B2 run and a B3 run; plus full runs/b2-*.jsonl and runs/b3-*.jsonl (or
$B2_LOG / $B3_LOG) when present (they skip otherwise; CI has none).
"""

import json
import os
import pathlib

import pytest

ROOT = pathlib.Path(__file__).resolve().parents[2]
POSE_GAP_S = 1.0                   # run_b2 logs a pose every second

def _full(name):
    """The newest full runs/<name>-*.jsonl (or $B2_LOG / $B3_LOG), or skip."""
    env = os.environ.get(f"{name.upper()}_LOG")
    found = [pathlib.Path(env)] if env else sorted((ROOT / "runs").glob(f"{name}-*.jsonl"), key=lambda p: p.stat().st_mtime)
    if not found:
        pytest.skip(f"no full {name.upper()} log")
    return [json.loads(line) for line in found[-1].read_text(encoding="utf-8").splitlines() if line.strip()]


