def recheck_t(records):
    shift = next((r for r in records if r.get("kind") == "shift"), None)
    if shift is None:
        return None
    core = {tuple(c) for c in shift.get("core", [])}
    return next((r["t"] for r in records if r.get("kind") == "plan" and r["t"] > shift["t"]
                 and r.get("status") == "ok" and not core & {tuple(c[:2]) for c in r.get("cells", [])}), None)


def bracket(records):
    """(pose t before or at the recheck, recheck t, pose t at or after it); None where missing."""
    t = recheck_t(records)
    poses = [r["t"] for r in records if r.get("kind") == "pose"]
    if t is None:
        return None, None, None
    return (max((p for p in poses if p <= t), default=None), t, min((p for p in poses if p >= t), default=None))


def check(records):
    before, t, after = bracket(records)
    assert t is not None, "no recheck in this log"
    assert before is not None and after is not None, f"no pose on both sides of the recheck at {t} s"
    assert before <= t <= after and after - before <= POSE_GAP_S, (before, t, after)
    return before, t, after


def test_real_logs_recheck_between_poses():
    assert check(REAL["b2-0"]) == (173.0, 173.7, 174.0)
    assert check(REAL["b3-0"]) == (226.0, 226.0, 226.0)          # a pose logged at the recheck itself


@pytest.mark.parametrize("name", ["b2", "b3"])
def test_full_real_logs(name):
    print(name, check(_full(name)))


def _without_poses(name, keep):
    return [r for r in REAL[name] if r["kind"] != "pose" or keep(r["t"])]


@pytest.mark.parametrize("records", [
    _without_poses("b2-0", lambda t: t <= 173.7),                 # no pose after the recheck
    _without_poses("b2-0", lambda t: t >= 173.7),                 # none before it
    _without_poses("b2-0", lambda t: t <= 173.0 or t >= 175.0),   # poses 2 s apart around it
    [r for r in REAL["b2-0"] if r["kind"] != "shift"],            # no shift: no recheck to place
])
def test_unplaceable_rechecks_fail(records):
    with pytest.raises(AssertionError):
        check(records)
